const int N = 1e5 + 10;
int pr[N];
bool is_prime(int x) {
	if(x <= 1) return false;
	for (int i = 2; i * i <= x; i++) 
		if(x%i == 0) return false;
	return true;
}
int main() {
	int cnt = 0;
	for(int i = 1; i <= N; i++) {
		if(is_prime(i)) pr[++cnt] = i;
	}
	int x = 259997;
	for(int i = 2; i <= 1e5; i++) {
		while(x % i == 0) {
			cout << i << " ";
			x /= i;
		}
	}
	return 0;
}
